[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$CapturePath,[Parameter(Mandatory=$true)][string]$OutputPath)
$ErrorActionPreference='Stop';$c=Get-Content $CapturePath -Raw -Encoding UTF8|ConvertFrom-Json;$block=@();$reason=$null;switch([string]$c.provenance){'SYNTHETIC_FIXTURE'{}'LIVE_READONLY'{$reason='LIVE_SNAPSHOT_INDEPENDENT_BINDING_REQUIRED'}default{$reason='UNSUPPORTED_CAPTURE_PROVENANCE'}};if(-not$c.stateEligible){$block+='CAPTURE_NOT_ELIGIBLE'};$sx=[single]$c.coordinateFrame.scaleX;$sy=[single]$c.coordinateFrame.scaleY;if(-not[float]::IsFinite($sx)-or-not[float]::IsFinite($sy)-or$sx-le0-or$sy-le0){$block+='INVALID_SCALE'}
function Trunc([double]$v){[int][Math]::Truncate($v)}
function Axis($lo,$hi,$scale,$limit){$inside=@();for($p=0;$p-lt$limit;$p++){$v=Trunc($p*$scale);if($v-ge$lo-and$v-lt$hi){$inside+=$p}};if($inside.Count-eq0){return $null};[ordered]@{first=$inside[0];lastExclusive=$inside[-1]+1}}
function Region($widget){$x=Axis $widget.logicalRect.left $widget.logicalRect.right $sx $c.process.clientWidth;$y=Axis $widget.logicalRect.top $widget.logicalRect.bottom $sy $c.process.clientHeight;if($null-eq$x-or$null-eq$y){$script:block+='ACTION_0X2B_SURFACE_NO_CLIENT_PIXELS';return $null};if(($x.lastExclusive-$x.first)-lt3-or($y.lastExclusive-$y.first)-lt3){$script:block+='ACTION_0X2B_SURFACE_NO_3X3_SAFE_MARGIN';return $null};$px=[int][Math]::Floor(($x.first+$x.lastExclusive-1)/2);$py=[int][Math]::Floor(($y.first+$y.lastExclusive-1)/2);[ordered]@{widgetPointer=$widget.widgetPointer;logicalRect=$widget.logicalRect;clientRect=[ordered]@{left=$x.first;top=$y.first;right=$x.lastExclusive;bottom=$y.lastExclusive};safePoint=[ordered]@{x=$px;y=$py;forwardLogical=[ordered]@{x=Trunc($px*$sx);y=Trunc($py*$sy)}}}}
$regions=@();if(-not$reason-and$block.Count-eq0){$r=Region $c.action0x2B.match;if($null-ne$r){$regions+=,$r}};$status=if($reason-or$block.Count){'UNBOUND'}else{'OFFLINE_RESOLVED'};$out=[ordered]@{schemaVersion=1;status=$status;reason=$reason;sourceProvenance=$c.provenance;originalRuntimeObserved=$false;action0x2B=[ordered]@{semantic='CURRENT_AUTHORITY_CARD_ACTION_WIDGET_FOR_COMMAND_0X2B_WARP_NAVIGATION';cardId=$c.manager65.cardId;actionIndex=$c.action0x2B.match.index;regions=$regions};automaticActivationPoint=$null;selectionPolicy='EXACT_DISCRETE_INVERSE_REGION_NO_AUTOMATIC_INPUT';blockers=@($block);operations=[ordered]@{writes=0;gameInputs=0}};$dir=Split-Path $OutputPath;if($dir-and-not(Test-Path $dir)){New-Item -ItemType Directory $dir|Out-Null};$out|ConvertTo-Json -Depth 15|Set-Content $OutputPath -Encoding UTF8
